record_rating_adjustment_active.definition:
CREATE OR REPLACE FUNCTION public.record_rating_adjustment_active(p_request_id uuid, p_player_id uuid, p_amount numeric, p_reason text, p_effective_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
  return public.record_rating_adjustment(
    p_request_id,
    p_player_id,
    p_amount,
    p_reason,
    p_effective_at,
    public._get_active_rating_version()
  );
end;
$function$

correct_rating_adjustment_active.definition:
CREATE OR REPLACE FUNCTION public.correct_rating_adjustment_active(p_adjustment_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
  return public.correct_rating_adjustment(
    p_adjustment_id,
    p_reason,
    public._get_active_rating_version()
  );
end;
$function$
